let audioCtx: AudioContext | null = null;

const getAudioContext = (): AudioContext | null => {
  if (typeof window === 'undefined') return null;
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    if (AudioContextClass) {
      audioCtx = new AudioContextClass();
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume();
  }
  return audioCtx;
};

export const playSound = (type: 'type' | 'correct' | 'miss' | 'finish', soundEnabled: boolean = true): void => {
  if (!soundEnabled) return;
  const ctx = getAudioContext();
  if (!ctx) return;

  const now = ctx.currentTime;

  if (type === 'type') {
    // 軽快なサイバー打鍵音
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sine';
    osc.frequency.setValueAtTime(600, now);
    osc.frequency.exponentialRampToValueAtTime(1200, now + 0.04);

    gain.gain.setValueAtTime(0.12, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.04);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start(now);
    osc.stop(now + 0.04);
  } else if (type === 'correct') {
    // 単語完了時の快いチャイム（2音）
    const tones = [587.33, 880]; // D5 -> A5
    tones.forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(freq, now + idx * 0.08);

      gain.gain.setValueAtTime(0.18, now + idx * 0.08);
      gain.gain.exponentialRampToValueAtTime(0.001, now + idx * 0.08 + 0.18);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now + idx * 0.08);
      osc.stop(now + idx * 0.08 + 0.18);
    });
  } else if (type === 'miss') {
    // ミスタイプ音（低めの濁ったバズ音）
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(180, now);
    osc.frequency.linearRampToValueAtTime(120, now + 0.08);

    gain.gain.setValueAtTime(0.15, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.08);

    osc.connect(gain);
    gain.connect(ctx.destination);

    osc.start(now);
    osc.stop(now + 0.08);
  } else if (type === 'finish') {
    // タイムアップのファンファーレ
    const notes = [523.25, 659.25, 783.99, 1046.5]; // C5, E5, G5, C6
    notes.forEach((freq, idx) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      const startTime = now + idx * 0.12;
      const duration = idx === notes.length - 1 ? 0.6 : 0.2;

      osc.type = 'sine';
      osc.frequency.setValueAtTime(freq, startTime);

      gain.gain.setValueAtTime(0.2, startTime);
      gain.gain.exponentialRampToValueAtTime(0.001, startTime + duration);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(startTime);
      osc.stop(startTime + duration);
    });
  }
};

import { useMemo } from 'react';
import { ResultModalProps } from './types';

const ResultModal = ({ stats, onRestart }: ResultModalProps) => {
  const { correctChars, missChars, completedWordsCount } = stats;

  const totalAttempts = correctChars + missChars;
  const accuracy = useMemo(() => {
    if (totalAttempts === 0) return 0;
    return Math.round((correctChars / totalAttempts) * 100);
  }, [correctChars, totalAttempts]);

  // 60秒ゲームなので1分あたりの単語数(WPM = 正解文字数 / 5)
  const wpm = useMemo(() => {
    return Math.round(correctChars / 5);
  }, [correctChars]);

  // 正解文字数に基づく評価ランク
  const rank = useMemo(() => {
    if (correctChars >= 250) return { label: 'S ランク', title: '神速のタイパー' };
    if (correctChars >= 190) return { label: 'A ランク', title: '上級タイパー' };
    if (correctChars >= 130) return { label: 'B ランク', title: '中級タイパー' };
    if (correctChars >= 70) return { label: 'C ランク', title: '初級タイパー' };
    return { label: 'D ランク', title: 'ビギナー' };
  }, [correctChars]);

  return (
    <div className="modal-overlay" role="dialog" aria-modal="true">
      <div className="result-card">
        <h2 className="result-title">タイムアップ！ 結果発表</h2>

        <div className="rank-badge">
          {rank.label} - {rank.title}
        </div>

        <div className="result-highlight">
          <span className="highlight-number">{correctChars}</span>
          <span className="highlight-unit">文字打鍵 / 60秒</span>
        </div>

        <div className="stats-grid">
          <div className="stat-item">
            <span className="stat-label">正解文字数</span>
            <span className="stat-value">{correctChars} 文字</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">ミス打鍵数</span>
            <span className="stat-value">{missChars} 回</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">正確率</span>
            <span className="stat-value">{accuracy}%</span>
          </div>
          <div className="stat-item">
            <span className="stat-label">打鍵速度 (WPM)</span>
            <span className="stat-value">{wpm} WPM</span>
          </div>
          <div className="stat-item" style={{ gridColumn: 'span 2' }}>
            <span className="stat-label">完走したお題数</span>
            <span className="stat-value">{completedWordsCount} 単語</span>
          </div>
        </div>

        <button
          type="button"
          className="restart-btn"
          onClick={() => onRestart?.()}
        >
          もう一度遊ぶ
        </button>
      </div>
    </div>
  );
};

export default ResultModal;

import { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, GameStats, WordItem } from './types';
import { WORDS_DATA, playSound } from './wordsData';
import ResultModal from './ResultModal';

const KEYBOARD_ROWS = [
  ['q', 'w', 'e', 'r', 't', 'y', 'u', 'i', 'o', 'p', '-'],
  ['a', 's', 'd', 'f', 'g', 'h', 'j', 'k', 'l'],
  ['z', 'x', 'c', 'v', 'b', 'n', 'm']
];

const INITIAL_TIME = 60;

const shuffleArray = <T,>(array: T[]): T[] => {
  const cloned = [...array];
  for (let i = cloned.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [cloned[i], cloned[j]] = [cloned[j], cloned[i]];
  }
  return cloned;
};

const App = () => {
  const [gameState, setGameState] = useState<GameState>('ready');
  const [timeLeft, setTimeLeft] = useState<number>(INITIAL_TIME);
  const [words, setWords] = useState<WordItem[]>([]);
  const [currentWordIndex, setCurrentWordIndex] = useState<number>(0);
  const [charIndex, setCharIndex] = useState<number>(0);
  const [soundEnabled, setSoundEnabled] = useState<boolean>(true);
  const [stats, setStats] = useState<GameStats>({
    totalTypedChars: 0,
    correctChars: 0,
    missChars: 0,
    completedWordsCount: 0
  });

  const hiddenInputRef = useRef<HTMLInputElement>(null);

  // ゲーム開始処理
  const startGame = useCallback(() => {
    const shuffled = shuffleArray(WORDS_DATA);
    setWords(shuffled);
    setCurrentWordIndex(0);
    setCharIndex(0);
    setTimeLeft(INITIAL_TIME);
    setStats({
      totalTypedChars: 0,
      correctChars: 0,
      missChars: 0,
      completedWordsCount: 0
    });
    setGameState('playing');

    setTimeout(() => {
      hiddenInputRef.current?.focus();
    }, 50);
  }, []);

  // お題スキップ処理
  const skipWord = useCallback(() => {
    if (gameState !== 'playing' || words.length === 0) return;
    playSound('miss', soundEnabled);
    setCharIndex(0);
    setCurrentWordIndex((prev) => (prev + 1) % words.length);
  }, [gameState, words.length, soundEnabled]);

  // カウントダウンタイマー
  useEffect(() => {
    if (gameState !== 'playing') return;

    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setGameState('finished');
          playSound('finish', soundEnabled);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState, soundEnabled]);

  // 1文字タイピング判定処理
  const handleCharInput = useCallback((inputChar: string) => {
    if (gameState !== 'playing' || words.length === 0) return;

    const currentWord = words[currentWordIndex];
    if (!currentWord) return;

    const targetChar = currentWord.romaji[charIndex];
    const isCorrect = inputChar.toLowerCase() === targetChar.toLowerCase();

    setStats((prev) => ({
      ...prev,
      totalTypedChars: prev.totalTypedChars + 1,
      correctChars: isCorrect ? prev.correctChars + 1 : prev.correctChars,
      missChars: isCorrect ? prev.missChars : prev.missChars + 1
    }));

    if (isCorrect) {
      playSound('type', soundEnabled);
      const nextCharIndex = charIndex + 1;

      if (nextCharIndex >= currentWord.romaji.length) {
        // 単語完了
        playSound('correct', soundEnabled);
        setStats((prev) => ({
          ...prev,
          completedWordsCount: prev.completedWordsCount + 1
        }));
        setCharIndex(0);
        setCurrentWordIndex((prev) => (prev + 1) % words.length);
      } else {
        setCharIndex(nextCharIndex);
      }
    } else {
      playSound('miss', soundEnabled);
    }
  }, [gameState, words, currentWordIndex, charIndex, soundEnabled]);

  // 物理キーボードイベント
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        skipWord();
        return;
      }

      if (gameState !== 'playing') {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          startGame();
        }
        return;
      }

      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey && !e.altKey) {
        e.preventDefault();
        handleCharInput(e.key);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState, handleCharInput, skipWord, startGame]);

  // スマホオンスクリーンキーボード入力
  const handleScreenKeyClick = (key: string) => {
    if (gameState !== 'playing') return;
    hiddenInputRef.current?.focus();
    handleCharInput(key);
  };

  const currentWord = words[currentWordIndex] || {
    id: 0,
    kanji: '',
    kana: '',
    romaji: ''
  };

  const targetNextChar = gameState === 'playing' && currentWord.romaji
    ? currentWord.romaji[charIndex]?.toLowerCase()
    : '';

  const typedRomaji = currentWord.romaji.slice(0, charIndex);
  const currentRomajiChar = currentWord.romaji[charIndex] || '';
  const remainingRomaji = currentWord.romaji.slice(charIndex + 1);

  return (
    <div className="app-container">
      {/* 非表示input (スマホ等でのフォーカス確保用) */}
      <input
        ref={hiddenInputRef}
        type="text"
        className="hidden-input"
        inputMode="none"
        aria-hidden="true"
        tabIndex={-1}
      />

      <header className="header">
        <div className="title-bar">
          <h1>⚡ CYBER TYPING 60</h1>
          <button
            type="button"
            className="sound-toggle-btn"
            onClick={() => setSoundEnabled((prev) => !prev)}
            title="サウンド切り替え"
          >
            {soundEnabled ? '🔊 サウンド ON' : '🔇 サウンド OFF'}
          </button>
        </div>
      </header>

      <main className="game-panel">
        {/* スコア・タイマーバー */}
        <div className="score-bar">
          <div className={`score-item timer-badge ${timeLeft <= 10 && gameState === 'playing' ? 'timer-active' : ''}`}>
            <span className="score-label">残り時間</span>
            <span className="score-val">{timeLeft}s</span>
          </div>
          <div className="score-item">
            <span className="score-label">打鍵数</span>
            <span className="score-val">{stats.correctChars}</span>
          </div>
          <div className="score-item">
            <span className="score-label">ミス数</span>
            <span className="score-val">{stats.missChars}</span>
          </div>
          <div className="score-item">
            <span className="score-label">クリア単語</span>
            <span className="score-val">{stats.completedWordsCount}</span>
          </div>
        </div>

        {gameState === 'ready' && (
          <div className="start-screen">
            <h2 className="kanji-text">ローマ字タイピング 60秒チャレンジ</h2>
            <p className="instruction-text">
              次々に表示される日本語のローマ字を打鍵して、60秒間で何文字打てるか限界に挑戦！<br />
              物理キーボード、または画面下のオンスクリーンキーボードで入力できます。<br />
              難しいお題は「スキップ (Esc)」が可能です。
            </p>
            <button
              type="button"
              className="start-btn"
              onClick={startGame}
            >
              ゲームスタート [Space]
            </button>
          </div>
        )}

        {gameState === 'playing' && (
          <div
            className="word-display-card"
            onClick={() => hiddenInputRef.current?.focus()}
          >
            <div className="kanji-text">{currentWord.kanji}</div>
            <div className="kana-text">{currentWord.kana}</div>
            <div className="romaji-container">
              <span className="romaji-typed">{typedRomaji}</span>
              <span className="romaji-current">{currentRomajiChar}</span>
              <span className="romaji-remaining">{remainingRomaji}</span>
            </div>
            <div style={{ marginTop: '12px', display: 'flex', gap: '8px' }}>
              <button
                type="button"
                className="sound-toggle-btn"
                onClick={(e) => {
                  e.stopPropagation();
                  skipWord();
                }}
              >
                ⏭️ このお題をスキップ (Esc)
              </button>
            </div>
          </div>
        )}

        {/* オンスクリーンキーボード */}
        <div className="keyboard-container">
          {KEYBOARD_ROWS.map((row, rowIdx) => (
            <div key={`row-${rowIdx}`} className="keyboard-row">
              {row.map((char) => {
                const isActive = targetNextChar === char;
                return (
                  <button
                    key={char}
                    type="button"
                    className={`key-cap ${isActive ? 'key-active' : ''}`}
                    onClick={() => handleScreenKeyClick(char)}
                  >
                    {char.toUpperCase()}
                  </button>
                );
              })}
            </div>
          ))}
          <div className="keyboard-row">
            <button
              type="button"
              className="key-cap key-space"
              onClick={() => {
                if (gameState === 'ready') startGame();
              }}
            >
              {gameState === 'ready' ? 'SPACE (スタート)' : 'SPACE BAR'}
            </button>
          </div>
        </div>
      </main>

      {/* 終了時のリザルトモーダル */}
      {gameState === 'finished' && (
        <ResultModal stats={stats} onRestart={startGame} />
      )}
    </div>
  );
};

export default App;
